def fast(n,edges,x):
 g=[[] for _ in range(n)]; r=[[] for _ in range(n)]
 for u,v in edges:g[u].append(v);r[v].append(u)
 d=[10**9]*(2*n);d[0]=0;q=[(0,0)]
 while q:
  z,s=heapq.heappop(q)
  if z!=d[s]:continue
  o,v=divmod(s,n)
  if v==n-1:return z
  for t,c in [((1-o)*n+v,x)]+[(o*n+w,1) for w in (r[v] if o else g[v])]:
   if z+c<d[t]:d[t]=z+c;heapq.heappush(q,(z+c,t))
def brute(n,edges,x):
 # repeated edge relaxations until stable
 E=[]
 for u,v in edges:E += [(u,v,1),(n+v,n+u,1)]
 for v in range(n):E.append((v,n+v,x));E.append((n+v,v,x))
