import sys
from collections import defaultdict

MOD = 998244353

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]
    arr=data[1:]
    # Factor every edge value.
    fac=[]
    primes=set()
    for x in arr:
        f=[]
        d=2
        while d*d<=x:
            if x%d==0:
                k=0
                while x%d==0:
                    x//=d; k+=1
                f.append((d,k)); primes.add(d)
            d+=1
        if x>1:
            f.append((x,1)); primes.add(x)
        fac.append(dict(f))

    answer=1
    for p in primes:
        # State (unshifted exponent at current position, minimum so far).
        # Values hold sum of p^(sum of exponents seen so far).
        dp={(0,0):1}
        for i in range(n-1):
            k=fac[i].get(p,0)
            if k:
                moves=(-k,k)
            else:
                moves=(0,)
            nd=defaultdict(int)
            for (h,mn),val in dp.items():
                for step in moves:
                    nh=h+step
                    nm=min(mn,nh)
                    key=(nh,nm)
                    nd[key]=(nd[key]+val*pow(p,nh,MOD))%MOD
            dp=nd
        total=0
        for (h,mn),val in dp.items():
            total=(total+val*pow(p,-n*mn,MOD))%MOD
        answer=answer*total%MOD
    print(answer)

if __name__=='__main__':
    main()

