import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:]
    limit = max(values)

    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for multiple in range(p * p, limit + 1, p):
                if spf[multiple] == multiple:
                    spf[multiple] = p

    nim_sum = 0
    for value in values:
        factors_with_multiplicity = 0
        while value > 1:
            value //= spf[value]
            factors_with_multiplicity += 1
        nim_sum ^= factors_with_multiplicity

    print('Anna' if nim_sum else 'Bruno')

