from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            events[b].append((a, i))

        largest = second = 0
        largest_id = -1
        gains = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for a, i in events[right]:
                if a > largest:
                    second = largest
                    largest = a
                    largest_id = i
                elif a > second:
                    second = a

            # For subarrays ending here, the start must be greater than
            # every active pair's smaller endpoint.
            total += right - largest
            if largest_id != -1:
                # Removing the uniquely largest restriction gains this many starts.
                gains[largest_id] += largest - second

        return total + max(gains)

