import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    edges = [None]
    for _ in range(m):
        edges.append((next(it) - 1, next(it) - 1, next(it)))

    queries = []
    closed = [False] * (m + 1)
    for _ in range(q):
        typ = next(it)
        if typ == 1:
            idx = next(it)
            queries.append((1, idx))
            closed[idx] = True
        else:
            queries.append((2, next(it) - 1, next(it) - 1))

    inf = 10**30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for idx in range(1, m + 1):
        if not closed[idx]:
            a, b, w = edges[idx]
            dist[a][b] = dist[b][a] = w

    # APSP in the graph after all closures.
    for k in range(n):
        row_k = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == inf:
                continue
            row_i = dist[i]
            for j in range(n):
                candidate = dik + row_k[j]
                if candidate < row_i[j]:
                    row_i[j] = candidate

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            _, x, y = query
            value = dist[x][y]
            answers.append(str(value if value < inf else -1))
        else:
            _, idx = query
            a, b, w = edges[idx]
            old = [row[:] for row in dist]
            for i in range(n):
                for j in range(i, n):
                    value = min(old[i][j], old[i][a] + w + old[b][j],
                                old[i][b] + w + old[a][j])
                    dist[i][j] = dist[j][i] = value

    sys.stdout.write('\n'.join(reversed(answers)))

if __name__ == '__main__':
    main()

