    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j]

        ans = 0
        for ones_needed in range(1, n + 1):
            # After the first operation, the value is ones_needed.
            x = ones_needed
            steps = 1
            while x > 1:
                x = x.bit_count()
                steps += 1
            if steps > k:
                continue

            count = 0
            ones_so_far = 0
            for i, bit in enumerate(s):
                if bit == '1':
                    remaining = n - i - 1
                    need = ones_needed - ones_so_far
                    if 0 <= need <= remaining:
                        count += comb[remaining][need]
                    ones_so_far += 1
            ans = (ans + count) % MOD
        return ans

