    for _ in range(n):
        U.append(data[p])
        D.append(data[p + 1])
        p += 2

    def feasible(h):
        lo = hi = None
        for u, d in zip(U, D):
            left = max(0, h - d)
            right = min(u, h)
            if lo is None:
                lo, hi = left, right
            else:
