import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Row-reduce the adjacency matrix over GF(2).
    pivots = []
    r = 0
    for c in range(n):
        q = next((i for i in range(r, n) if (rows[i] >> c) & 1), None)
        if q is None:
            continue
        rows[r], rows[q] = rows[q], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivots.append(c)
        r += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    basis = []
    for f in free:
        vec = 1 << f
        for i, c in enumerate(pivots):
            if (rows[i] >> f) & 1:
                vec |= 1 << c
        basis.append(vec)

    # Use one integer bit per nullspace basis vector.
    labels = [0] * n
    for j, vec in enumerate(basis):
        bit = 1 << j
        for v in range(n):
            if (vec >> v) & 1:
                labels[v] |= bit

    if any(x == 0 for x in labels):
        print('No')
        return

    # Multiplying a solution by 4 preserves every XOR equation and keeps
    # values positive; use it when the allowed range permits it.
    if m and max(labels) * 4 < (1 << 60):
        labels = [x * 4 for x in labels]
    print('Yes')
    print(*labels)

