import math

N = int(sys.stdin.readline())

# Since N = (x-y)(x^2+xy+y^2) and the second factor is at least
# (x-y)^2, d = x-y must satisfy d^3 <= N.
lo, hi = 0, 1
while hi ** 3 <= N:
    hi *= 2
while lo + 1 < hi:
    mid = (lo + hi) // 2
    if mid ** 3 <= N:
        lo = mid
    else:
        hi = mid

for d in range(1, lo + 1):
    if N % d:
        continue
    # N/d = 3y^2 + 3dy + d^2, so its quadratic
    # discriminant is 12*N/d - 3*d^2 = (6y + 3d)^2.
    disc = 12 * (N // d) - 3 * d * d
    if disc < 0:
        continue
    s = math.isqrt(disc)
    if s * s == disc and s > 3 * d and (s - 3 * d) % 6 == 0:
        y = (s - 3 * d) // 6
        print(y + d, y)
        break
else:
    print(-1)

