class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # The digit at position i on the left also appears at position j
        # on the right. Its coefficient is the sum of those decimal-place
        # weights modulo k.
        powers = [1] * n
        for e in range(1, n):
            powers[e] = powers[e - 1] * 10 % k

        coeff = []
        for i in range(m):
            j = n - 1 - i
            value = powers[n - 1 - i]
            if j != i:
                value += powers[n - 1 - j]
            coeff.append(value % k)

        # suffix[i][r] means the variables i..m-1 can contribute residue r.
        suffix = [bytearray(k) for _ in range(m + 1)]
        suffix[m][0] = 1
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            nxt = suffix[i + 1]
            cur = suffix[i]
            for r in range(k):
                if nxt[r]:
                    for digit in range(10):
                        cur[(r + digit * c) % k] = 1

        # Greedily choose each left-half digit from largest to smallest,
        # retaining only choices that permit a divisible completion.
        left = []
        rem = 0
        for i, c in enumerate(coeff):
            smallest = 1 if i == 0 else 0
            for digit in range(9, smallest - 1, -1):
                new_rem = (rem + digit * c) % k
                if suffix[i + 1][(-new_rem) % k]:
                    left.append(str(digit))
                    rem = new_rem
                    break

        left = ''.join(left)
        if n % 2:
            return left + left[:-1][::-1]
        return left + left[::-1]

