    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, rest = p.split('*', 1)
        b, c = rest.split('*', 1)
        n = len(s)

        def occurrences(pattern):
            if not pattern:
                return range(n + 1)
            m = len(pattern)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = pi[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                pi[i] = j
            found = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = pi[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    found.append(i - m + 1)
                    j = pi[j - 1]
            return found

        starts_a = occurrences(a)
        starts_b = occurrences(b)
        starts_c = occurrences(c)
        best = n + 1
        for middle in starts_b:
            if a:
                idx = bisect.bisect_right(starts_a, middle - len(a)) - 1
                if idx < 0:
                    continue
                start = starts_a[idx]
            else:
                start = middle

            if c:
                idx = bisect.bisect_left(starts_c, middle + len(b))
                if idx == len(starts_c):
                    continue
                end = starts_c[idx] + len(c)
            else:
                end = middle + len(b)

            best = min(best, end - start)
