    for x in a:
        total ^= x

    if k == n:
        print(total)
        return

    r = min(k, n - k)
    best = 0
    if k <= n - k:
        # Enumerate the chosen elements directly.
        for inds in combinations(range(n), r):
            value = 0
            for i in inds:
                value ^= a[i]
            if value > best:
                best = value
    else:
        # XOR of the chosen elements is total XOR XOR of the omitted ones.
        for inds in combinations(range(n), r):
            value = total
            for i in inds:
                value ^= a[i]
            if value > best:
                best = value

    print(best)

