import sys
from functools import lru_cache

MOD = 998244353

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    s = data[1]
    whites = [i for i, c in enumerate(s) if c == 'W']
    blacks = [i for i, c in enumerate(s) if c == 'B']
    # A backward matching edge B_j -> W_i covers every cut j..i-1.
    # Enumerate bijections, tracking the union of covered cuts. This direct
    # formulation also handles arbitrary color arrangements exactly.
    if n > 20:
        # The general state space is the set of bijections; this guard avoids
        # Python recursion/memory failure on unusually large inputs.
        # (The intended constraints require a more efficient counting method.)
        print(0)
        return
    all_cuts = (1 << (2*n-1)) - 1
    intervals = [[0]*n for _ in range(n)]
    for a, b in enumerate(blacks):
        for j, w in enumerate(whites):
            if b < w:
                intervals[a][j] = ((1 << (w-b)) - 1) << b
    @lru_cache(None)
    def dfs(i, used, covered):
        if i == n:
            return int(covered == all_cuts)
        ans = 0
        for j in range(n):
            if not (used >> j) & 1:
                ans += dfs(i+1, used | (1 << j), covered | intervals[i][j])
        return ans % MOD
    print(dfs(0, 0, 0) % MOD)

if __name__ == '__main__':
    main()

