from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Minimum prefix sum seen at each prefix-index residue modulo k.
        mins = [None] * k
        mins[0] = 0
        prefix = 0
        best = None

        for i, value in enumerate(nums, 1):
            prefix += value
            residue = i % k

            # Matching prefix-index residues mean the subarray length is divisible by k.
            if mins[residue] is not None:
                candidate = prefix - mins[residue]
                if best is None or candidate > best:
                    best = candidate

            if mins[residue] is None or prefix < mins[residue]:
                mins[residue] = prefix

        return best

