import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        if len(str(m)) != digits:
            return -1

        limit = 10 ** digits
        is_prime = [True] * limit
        is_prime[0] = is_prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if is_prime[p]:
                for x in range(p * p, limit, p):
                    is_prime[x] = False

        if is_prime[n] or is_prime[m]:
            return -1

        min_value = 10 ** (digits - 1)
        place_values = [10 ** i for i in range(digits)]
        dist = [float('inf')] * limit
        dist[n] = n  # Include the starting value in the total cost.
        pq = [(n, n)]

        while pq:
            cost, value = heapq.heappop(pq)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            for place in place_values:
                digit = (value // place) % 10
                if digit < 9:
                    nxt = value + place
                    if nxt >= min_value and not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < dist[nxt]:
                            dist[nxt] = new_cost
                            heapq.heappush(pq, (new_cost, nxt))
                if digit > 0:
                    nxt = value - place
                    if nxt >= min_value and not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < dist[nxt]:
                            dist[nxt] = new_cost
                            heapq.heappush(pq, (new_cost, nxt))

        return -1

