def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    best = [None, None]  # maximum sum of a valid survivor chain ending at each parity

    for i, x in enumerate(data[1:], 1):
        parity = i & 1
        base = 0 if parity == 1 else None  # a chain may start only at an odd index
        previous = best[parity ^ 1]
        if previous is not None:
            base = previous if base is None else max(base, previous)
        if base is not None:
            value = base + x
            if best[parity] is None or value > best[parity]:
                best[parity] = value

    answer = best[n & 1]
    if n % 2 == 0:
        answer = max(0, answer if answer is not None else 0)
    print(answer)

