class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n, m = len(source), len(pattern)
        is_target = bytearray(n)
        for i in targetIndices:
            is_target[i] = 1

        # Minimum number of target positions used by a subsequence embedding
        # of each prefix of pattern.
        inf = n + 1
        dp = [inf] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            # Descending order ensures this source position is used at most once.
            for j in range(m - 1, -1, -1):
                if ch == pattern[j] and dp[j] < inf:
                    cost = dp[j] + is_target[i]
                    if cost < dp[j + 1]:
                        dp[j + 1] = cost

        return len(targetIndices) - dp[m]

