class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # State (left color, right color) for one pair equidistant from the ends.
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        # Process pairs from the outside toward the center. Consecutive pairs
        # must differ on both the left and the right side.
        for i in range(1, n // 2):
            ndp = [0] * len(states)
            for j, (a, b) in enumerate(states):
                pair_cost = cost[i][a] + cost[n - 1 - i][b]
                best_prev = min(
                    dp[k]
                    for k, (x, y) in enumerate(states)
                    if x != a and y != b
                )
                ndp[j] = best_prev + pair_cost
            dp = ndp

        return min(dp)

