class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        base = s.count('1')
        t = '1' + s + '1'

        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        answer = base
        # A candidate is an internal run of ones in the augmented string.
        # Trading it merges its adjacent zero-runs, whose cells become active.
        for i in range(1, len(runs) - 1):
            if runs[i][0] == '1':
                answer = max(answer, base + runs[i - 1][1] + runs[i + 1][1])

        return answer

