class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set("aeiou")
        answer = 0
        n = len(word)

        # Enumerate each starting position. Once the consonant count exceeds
        # k, extending the substring cannot make it valid again.
        for left in range(n):
            seen_vowels = set()
            consonants = 0
            for right in range(left, n):
                char = word[right]
                if char in vowels:
                    seen_vowels.add(char)
                else:
                    consonants += 1

                if consonants > k:
                    break
                if consonants == k and len(seen_vowels) == 5:
                    answer += 1

        return answer

