from typing import List

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        # Every valid copy differs from original by one constant integer offset.
        low = max(bounds[i][0] - original[i] for i in range(len(original)))
        high = min(bounds[i][1] - original[i] for i in range(len(original)))
        return max(0, high - low + 1)

